307	    /** The claims of the ids on the sheet in list order: the people in the order they were added,
308	     *  each person's claims newest first; ids not on the sheet are left out. */
309	    @Transactional(readOnly = true)
310	    public List<Long> inListOrder(String sheetId, Collection<Long> ids) {
311	        Set<Long> wanted = new HashSet<>(ids);
312	        Map<Long, Integer> personOrder = new HashMap<>();
313	        List<Person> theirs = people.findBySheetIdOrderByIdAsc(sheetId);
314	        for (int i = 0; i < theirs.size(); i++) {
315	            personOrder.put(theirs.get(i).getId(), i);
316	        }
317	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
318	                .filter(c -> wanted.contains(c.getId()))
319	                .sorted(Comparator.comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
320	                .map(Claim::getId)
321	                .toList();
