324	    /** Add a claim for a person on the sheet; a missing date takes the sheet's today. Refused
325	     *  (423) when the date is in a closed period, (422) when it is after the person's
326	     *  retirement date, and (422) when it is a correction (a negative amount) that does not name
327	     *  the number of a SETTLED claim of the same person. */
328	    @Transactional
329	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
330	            String corrects) {
331	        Person person = people.findByIdAndSheetId(personId, sheetId)
332	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
333	        LocalDate on = date != null ? date : sheets.today(sheetId);
334	        refuseIfClosed(sheetId, on);
335	        refuseIfRetired(person, on);
336	        String corrected = correctedBy(sheetId, personId, amount, corrects);
337	        RollupService.Snapshot before = rollup.snapshot(sheetId);
338	        int terms = sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on), on)).orElse(Sheet.DEFAULT_TERMS);
339	        Claim fresh = new Claim(sheetId, personId, amount, on, on.plusDays(terms), noteOf(note));
340	        fresh.setCorrects(corrected);
341	        // the sheet is locked (refuseIfClosed), so two claims added at once are listed one after the other
342	        fresh.setListed(claims.findLastListed(sheetId) + 1);
343	        Claim claim = claims.saveAndFlush(fresh);
344	        logStatus(user, person, claim);
345	        record("CLAIM_ADDED", user, person, claim);
346	        rollup.recordChanges(sheetId, user, before);
347	        return claim;
348	    }
