350	    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today.
351	     *  Refused (409) once the claim is no longer a DRAFT (an open claim is voided and a new one
352	     *  added instead), and (423) when its old or new date is in a closed period, and (422) when the new
353	     *  date is after the person's retirement date, or when it is a correction that does not name
354	     *  the number of a SETTLED claim of the same person. */
355	    @Transactional
356	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
357	            String corrects) {
358	        Claim claim = claims.findForUpdate(id, sheetId)
359	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
360	        LocalDate on = date != null ? date : sheets.today(sheetId);
361	        refuseIfClosed(sheetId, claim.getDate());
362	        if (claim.getStatus() != ClaimStatus.DRAFT) {
363	            throw new ResponseStatusException(HttpStatus.CONFLICT,
364	                    "A " + claim.getStatus() + " claim cannot be edited");
365	        }
366	        refuseIfClosed(sheetId, on);
367	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
368	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
369	        refuseIfRetired(person, on);
370	        String corrected = correctedBy(sheetId, person.getId(), amount, corrects);
371	        RollupService.Snapshot before = rollup.snapshot(sheetId);
372	        claim.setAmount(amount);
373	        claim.setCorrects(corrected);
374	        claim.setDate(on);
375	        claim.setNote(noteOf(note));
376	        claims.flush();
377	        record("CLAIM_EDITED", user, person, claim);
378	        rollup.recordChanges(sheetId, user, before);
379	        return claim;
380	    }
