382	    /** Move a claim to a new status; a move its status does not allow is refused (409), as is
383	     *  settling by the user who opened the claim (403), settling a PENDING claim (409: it is
384	     *  approved or rejected instead), and any move of a claim dated in a closed period (423). A
385	     *  clerk settling a claim whose due is above the sheet's clerk limit sends it to PENDING. */
386	    @Transactional
387	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus to) {
388	        Claim claim = claims.findForUpdate(id, sheetId)
389	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
390	        refuseIfClosed(sheetId, claim.getDate());
391	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
392	                || !claim.getStatus().canMoveTo(to)) {
393	            throw new ResponseStatusException(HttpStatus.CONFLICT,
394	                    "A " + claim.getStatus() + " claim cannot become " + to);
395	        }
396	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
397	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
398	                    "The user who opened a claim cannot settle it");
399	        }
400	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
401	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
402	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
403	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
404	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
405	            // above the clerk limit: a steward approves or rejects it
406	            to = ClaimStatus.PENDING;
407	        }
408	        RollupService.Snapshot before = rollup.snapshot(sheetId);
409	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
410	        String number = claim.getNumber();
411	        claim.setStatus(to);
412	        if (to == ClaimStatus.OPEN) {
413	            number = nextNumber(sheetId, claim.getDate());
414	            claim.setNumber(number);
415	            claim.setOpenedBy(user);
416	        } else if (to == ClaimStatus.SETTLED) {
417	            claim.setSettledDue(settling);
418	        }
419	        claims.flush();
420	        logStatus(user, person, claim);
421	        String event = switch (to) {
422	            case OPEN -> "CLAIM_OPENED";
423	            case PENDING -> "CLAIM_PENDING";
424	            case SETTLED -> "CLAIM_SETTLED";
425	            case VOID -> "CLAIM_VOIDED";
426	            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
427	        };
428	        if (to == ClaimStatus.SETTLED) {
429	            record(event, user, person, claim, number, " due=" + dueText(claim.getSettledDue()));
430	        } else {
431	            record(event, user, person, claim, number);
432	        }
433	        rollup.recordChanges(sheetId, user, before);
434	        return claim;
435	    }
436	
437	    /** A steward approves a PENDING claim: it becomes SETTLED, its due (its live figure, with its
438	     *  late charge) frozen now. Refused (409) unless PENDING, (403) for a clerk or the user who
439	     *  opened it, and (423) when it is dated in a closed period. */
440	    @Transactional
441	    public Claim approve(String sheetId, String user, long id) {
442	        Claim claim = pendingForSteward(sheetId, user, id);
443	        if (user.equals(claim.getOpenedBy())) {
444	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
445	                    "The user who opened a claim cannot approve it");
446	        }
447	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
448	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
449	        RollupService.Snapshot before = rollup.snapshot(sheetId);
450	        BigDecimal due = shownDueOf(claim, person);
451	        claim.setStatus(ClaimStatus.SETTLED);
452	        claim.setSettledDue(due);
453	        claims.flush();
454	        logStatus(user, person, claim);
455	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), " due=" + dueText(due));
456	        rollup.recordChanges(sheetId, user, before);
457	        return claim;
458	    }
459	
460	    /** A steward re-settles a SETTLED claim: its due is frozen again at the figure it would show
461	     *  today as an open claim bound by no statement (today's rates, grades, floor and late
462	     *  charge). Refused (404) when missing, (423) when dated in a closed period, (403) for anyone
463	     *  but a steward, and (409) unless SETTLED. */
464	    @Transactional
465	    public Claim resettle(String sheetId, String user, long id) {
466	        Claim claim = claims.findForUpdate(id, sheetId)
467	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
468	        refuseIfClosed(sheetId, claim.getDate());
469	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
470	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
471	        }
472	        if (claim.getStatus() != ClaimStatus.SETTLED) {
473	            throw new ResponseStatusException(HttpStatus.CONFLICT,
474	                    "Only a SETTLED claim is re-settled, not a " + claim.getStatus() + " one");
475	        }
476	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
477	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
478	        RollupService.Snapshot before = rollup.snapshot(sheetId);
479	        BigDecimal old = claim.getSettledDue();
480	        BigDecimal due = LateCharge.of(sheets.find(sheetId)).addToOpen(claim, dueOf(claim, person), roundingOf(claim));
481	        claim.setSettledDue(due);
482	        claims.flush();
483	        logStatus(user, person, claim);
484	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(),
485	                " old=" + dueText(old) + " new=" + dueText(due));
486	        rollup.recordChanges(sheetId, user, before);
487	        return claim;
488	    }
489	
490	    /** A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by the
491	     *  person's last statement if that statement bound it. Refused (409) unless PENDING, (403) for
492	     *  a clerk, and (423) when it is dated in a closed period. */
493	    @Transactional
494	    public Claim reject(String sheetId, String user, long id, String reason) {
495	        Claim claim = pendingForSteward(sheetId, user, id);
496	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
497	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
498	        RollupService.Snapshot before = rollup.snapshot(sheetId);
499	        claim.setStatus(ClaimStatus.OPEN);
500	        claims.flush();
501	        logStatus(user, person, claim);
502	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), " reason=" + reason);
503	        rollup.recordChanges(sheetId, user, before);
504	        return claim;
505	    }
