507	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
508	     *  number and date, is listed as the new person's newest claim, and loses any figure a
509	     *  statement bound it to (live again until the new person's next statement). Refused (404)
510	     *  when the claim or person is missing, (423) when it is dated in a closed period, (403) for a
511	     *  clerk, (409) when SETTLED or VOID or already the person's, and (422) when it is dated after
512	     *  the new person's retirement date. */
513	    @Transactional
514	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
515	        Claim claim = claims.findForUpdate(id, sheetId)
516	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
517	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
518	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
519	        refuseIfClosed(sheetId, claim.getDate());
520	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
521	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward reassigns a claim");
522	        }
523	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
524	            throw new ResponseStatusException(HttpStatus.CONFLICT,
525	                    "A " + claim.getStatus() + " claim cannot be reassigned");
526	        }
527	        if (claim.getPersonId() == toPersonId) {
528	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
529	        }
530	        refuseIfRetired(to, claim.getDate());
531	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
532	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
533	        RollupService.Snapshot before = rollup.snapshot(sheetId);
534	        claim.setPersonId(to.getId());
535	        claim.unbind();
536	        claim.setListed(claims.findLastListed(sheetId) + 1);
537	        claims.flush();
538	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
539	                " from=" + from.getName() + " to=" + to.getName());
540	        rollup.recordChanges(sheetId, user, before);
541	        return claim;
542	    }
