544	    /** The PENDING claim a steward decides on: refused (404) when missing, (423) when dated in a
545	     *  closed period, (409) unless PENDING, and (403) when the user is not a steward. */
546	    private Claim pendingForSteward(String sheetId, String user, long id) {
547	        Claim claim = claims.findForUpdate(id, sheetId)
548	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
549	        refuseIfClosed(sheetId, claim.getDate());
550	        if (claim.getStatus() != ClaimStatus.PENDING) {
551	            throw new ResponseStatusException(HttpStatus.CONFLICT,
552	                    "Only a PENDING claim is approved or rejected, not a " + claim.getStatus() + " one");
553	        }
554	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
555	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
556	                    "Only a steward approves or rejects a PENDING claim");
557	        }
558	        return claim;
559	    }
560	
561	    /** Write the claim's status now to its log: by the user, on the sheet's today, with the due
562	     *  it shows at this moment. */
563	    private void logStatus(String user, Person person, Claim claim) {
564	        BigDecimal due = shownDueOf(claim, person);
565	        log.save(new ClaimLog(claim.getSheetId(), claim.getId(), claim.getStatus(), user,
566	                sheets.today(claim.getSheetId()), due == null ? null : due.setScale(2, RoundingMode.HALF_EVEN)));
567	    }
568	
569	    private static String dueText(BigDecimal due) {
570	        return due == null ? "n/a" : due.toPlainString();
571	    }
572	
573	    /** Take a statement of a person: record their due-total now, and bind each of their claims
574	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold) to its figure now; the others
575	     *  are left unbound. */
576	    @Transactional
577	    public Statement statement(String sheetId, String user, long personId) {
578	        Person person = people.findForUpdate(personId, sheetId)
579	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
580	        LocalDate today = sheets.today(sheetId);
581	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
582	        RollupService.Snapshot before = rollup.snapshot(sheetId);
583	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person)).toList();
584	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
585	        for (Claim c : theirs) {
586	            if (counts(c, person)) {
587	                // the statement binds the figure; the late charge keeps following the sheet's today
588	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
589	            } else {
590	                c.unbind();
591	            }
592	        }
593	        claims.flush();
594	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
595	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
596	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
597	        rollup.recordChanges(sheetId, user, before);
598	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
599	    }
600	
601	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
602	     *  and the sheet's today on or after it) the next within the period containing the date
603	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
604	    private String nextNumber(String sheetId, LocalDate date) {
605	        if (!sheets.periodNumberingOn(sheetId)) {
606	            return String.valueOf(sheets.nextClaimNumber(sheetId));
607	        }
608	        // held until the transaction ends, so two claims opened at once are numbered one after the other
609	        sheets.lock(sheetId);
610	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
611	        int last = claims.findNumbers(sheetId).stream()
612	                .filter(n -> n.startsWith(prefix))
613	                .map(n -> n.substring(prefix.length()))
614	                .filter(n -> n.matches("\\d{1,9}"))
615	                .mapToInt(Integer::parseInt)
616	                .max().orElse(0);
617	        return prefix + (last + 1);
618	    }
619	
620	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
621	     *  the transaction ends so a period cannot be closed meanwhile. */
622	    private void refuseIfClosed(String sheetId, LocalDate date) {
623	        sheets.lock(sheetId);
624	        periods.refuseIfClosed(sheetId, date);
625	    }
626	
627	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
628	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
629	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
630	        if (amount.signum() >= 0) {
631	            return null;
632	        }
633	        if (corrects == null
634	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
635	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
636	                    "A negative amount must correct a settled claim of the same person");
637	        }
638	        return corrects;
639	    }
640	
641	    /** Refuse (422) a claim dated after its person's retirement date. */
642	    private static void refuseIfRetired(Person person, LocalDate date) {
643	        if (person.retiredBefore(date)) {
644	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
645	                    "The date is after the person's retirement date");
646	        }
647	    }
648	
649	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
650	     *  do, but not an open one dated within a hold of its person unless bound by a statement. */
651	    private static boolean counts(Claim c, Person person) {
652	        return c.getStatus() == ClaimStatus.SETTLED
653	                || (c.getStatus().isOpen() && (c.isBound() || !person.heldOn(c.getDate())));
654	    }
655	
656	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
657	     *  charge on top. */
658	    private BigDecimal shownDueOf(Claim claim, Person person) {
659	        if (claim.getSettledDue() != null) {
660	            return claim.getSettledDue();
661	        }
662	        return LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim));
663	    }
664	
665	    /** A claim's figure before any late charge: the one a statement bound it to (null: n/a), else
666	     *  (unbound, or PENDING) its live due. */
667	    private BigDecimal figureOf(Claim claim, Person person) {
668	        return claim.isBound() ? claim.getStatedDue() : dueOf(claim, person);
669	    }
670	
671	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
672	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
673	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
674	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
675	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
676	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
677	            return null;
678	        }
679	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
680	    }
681	
682	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
683	     *  100, rounded as its rounding policy has it, raised to the sheet's floor in force on its date (a correction's never is); null with no rate in force then. */
684	    private BigDecimal dueOf(Claim claim, Person person) {
685	        BigDecimal floor = sheets.floorOn(claim.getSheetId(), claim.getDate());
686	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
687	                .map(Rate::getPct)
688	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
689	                .map(due -> claim.isCorrection() ? due : due.max(floor))
690	                .orElse(null);
691	    }
692	
693	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
694	     *  correction the date of the claim it corrects. */
695	    private RoundingMode roundingOf(Claim claim) {
696	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
697	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
698	                        .map(Claim::getDate).orElse(claim.getDate());
699	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
700	    }
701	
702	    private void record(String event, String user, Person person, Claim claim) {
703	        record(event, user, person, claim, claim.getNumber());
704	    }
705	
706	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
707	    private void record(String event, String user, Person person, Claim claim, String number) {
708	        record(event, user, person, claim, number, "");
709	    }
710	
711	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
712	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
713	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
714	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
715	    }
716	
717	    private static String noteOf(String note) {
718	        return note == null ? "" : note.trim();
719	    }
720	}
