    /** The late charge of a sheet as it is now, at the late percent in force on each claim's date;
     *  a sheet never loaded charges nothing. */
    public static LateCharge of(Optional<Sheet> sheet) {
        return new LateCharge(sheet.map(Sheet::getToday).orElseGet(LocalDate::now),
                on -> sheet.map(s -> s.latePctOn(on)).orElse(Sheet.DEFAULT_LATE_PCT));
    }

    /** The claim's figure (null: n/a, which stays n/a) with its late charge, rounded by {@code mode}, added. */
    public BigDecimal addTo(Claim claim, BigDecimal figure, RoundingMode mode) {
        if (!claim.getStatus().isOpen()) {
            return figure;
        }
        return addToOpen(claim, figure, mode);
    }

    /** The figure with the late charge the claim would gain were it open, whatever its status. */
    public BigDecimal addToOpen(Claim claim, BigDecimal figure, RoundingMode mode) {
        if (figure == null || claim.isCorrection()) {
            return figure;
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
        if (overdue <= 0) {
            return figure;
        }
        BigDecimal steps = BigDecimal.valueOf(overdue / STEP_DAYS);
        return figure.add(figure.multiply(pctOn.apply(claim.getDate())).multiply(steps).divide(BigDecimal.valueOf(100), 2, mode));
    }
}
  protected readonly grades = GRADES;
  protected readonly people = signal<Person[]>([]);
  /** The people the list shows: retired ones (any with a retirement date) only with "show retired" on. */
  protected readonly shownPeople = computed(() =>
    this.session.showRetired() ? this.people() : this.people().filter((p) => p.retiredFrom === null));
  /** Every claim on the sheet, newest first. */
  protected readonly claims = signal<Claim[]>([]);
  /** The holds of each person with any, by person id: their open (OPEN or PENDING) claims dated within one count in no live total. */
  private readonly holdsById = computed(() => new Map(this.people().filter((p) => p.held).map((p) => [p.id, p.holds])));
  /** Whether a claim counts in the live totals: open (OPEN or PENDING) and SETTLED ones, but not an open one
   *  dated within a hold of its person unless bound by a statement. */
  private readonly countsLive = computed(() => {
    const holds = this.holdsById();
    return (c: Claim) => counts(c) && !(isOpen(c) && !isBound(c) && heldOn(holds.get(c.personId) ?? [], c.date));
  });
  /** Each person's claims (newest first) and claimed in cents (counting claims only), by person id. */
  private readonly byPerson = computed(() => {
    const out = new Map<number, { claims: Claim[]; cents: number }>();
    const live = this.countsLive();
    for (const c of this.claims()) {
      const entry = out.get(c.personId) ?? { claims: [], cents: 0 };
      entry.claims.push(c);
      if (live(c)) entry.cents += cents(c.amount);
      out.set(c.personId, entry);
    }
    return out;
  });
  /** The sheet's rates (a percent with two decimals), each for a grade from a from-date. */
  protected readonly rates = signal<Rate[]>([]);
  /** What every late charge follows: the sheet's today and late percent. */
  private readonly lateness = computed<Lateness>(() => ({
    today: this.session.today(), latePctOn: (d) => this.session.latePctOn(d),
  }));
  /** Each person's due-total in cents, by person id: the sum of the dues their OPEN and SETTLED
